import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"33、【遁】 艮下乾上","description":"子夏易传 - 33、【遁】 艮下乾上","frontmatter":{"title":"33、【遁】 艮下乾上","description":"子夏易传 - 33、【遁】 艮下乾上"},"headers":[],"relativePath":"zh/classics/zixia/035.md","filePath":"zh/classics/zixia/035.md"}'),i={name:"zh/classics/zixia/035.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_33、【遁】-艮下乾上" tabindex="-1">33、【遁】 艮下乾上 <a class="header-anchor" href="#_33、【遁】-艮下乾上" aria-label="Permalink to “33、【遁】 艮下乾上”">​</a></h1><p>卦辞：遯亨，小利貞。</p><p>彖曰：遯亨，遯而亨也。剛當位而應與時行也。小利貞，浸而長也。遯之時，義大矣哉。</p><p>子夏：陰長而君子外於時也。隱其道，逃其情，從而正之，而後乃亨。夫彼之生也，微其終大而不可禦者，時之來也。故君子觀其兆，而不待其至也。當位而應，猶不果制，與時行而已矣。陰浸而長，其患未害，我志猶行也，故小利而貞。剛而應柔，和而不同，遯而反制，非大徳不能消息也。</p><p>象曰：天下有山，遯。君子以逺小人，不惡而嚴。</p><p>子夏：山侵於天，下通上也。君子逃情於小人，不以力爭，嚴以制也。</p><p>初六，遯尾，厲。勿用有攸往。</p><p>象曰：遯尾之厲，不往何災也。</p><p>子夏：遯，以逃避患也。患未至而首遯之，則逺於患矣。陰過二矣，而後遯焉，遯之尾也。見而逃之，反相疑也。不往而和，則何災哉。</p><p>六二，執之用黄牛之革，莫之勝説。</p><p>象曰：執用黄牛，固志也。</p><p>子夏：小人之道，狹而鮮親，至於履位，人多逃也。則以法執也，或係之以利，質之以愛，然後人不得去。堅其志而不可拔也，乃得小人之中，而獲其順矣。</p><p>九三，係遯有疾厲，畜臣妾吉。</p><p>象曰：係遯之厲有疾，憊也。畜臣妾吉，不可大事也。</p><p>子夏：係志於陰，不能遯也。為小人所制，危憊之道也。施於畜臣妾，吉也。係於鄙賤，豈可大事乎。</p><p>九四，好遯君子吉，小人否。</p><p>象曰：君子好遯，小人否也。</p><p>子夏：君子知幾絶而好遯小人，情係不能遯也。</p><p>九五，嘉遯，貞吉。</p><p>象曰：嘉遯貞吉，以正志也。</p><p>子夏：當位相應，能制於内，遯情而治，志在乎正，可謂遯之嘉也。</p><p>上九，肥遯，无不利。</p><p>象曰：肥遯无不利，无所疑也。</p><p>子夏：過於卦外，無應小人，不勞慮於進退，可謂遯之肥而無不利也。</p>',24)])])}const h=a(i,[["render",r]]);export{f as __pageData,h as default};
